    animationRef.current = requestAnimationFrame(animate);
  }, []);

  // Initialize simulation when component mounts
  useEffect(() => {
    initializeBalls();
    animate();

    // Cleanup animation on unmount
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [animate]);

  // Reset simulation
  const resetSimulation = () => {
    initializeBalls();
    wallImpactsRef.current = []; // Clear wall impacts
  };

  return (
    <div className="ball-simulation">
      <h1>Bouncing Balls Simulation</h1>
      <div className="simulation-container">
        <canvas
          ref={canvasRef}
          width={CANVAS_WIDTH}
          height={CANVAS_HEIGHT}
          className="simulation-canvas"
        />
      </div>
      <div className="controls">
        <button onClick={resetSimulation} className="reset-button">
          Reset Simulation
        </button>
        <div className="info">
          <p>5 balls with varying masses bouncing around in a box!</p>
          <p>Ball size reflects mass - bigger balls are heavier.</p>
          <p>Heavier balls generally move slower, but all have unique speeds.</p>
          <p><strong>Physics:</strong> Balls collide with each other! Collision physics considers mass and velocity.</p>
          <p><strong>Animation:</strong> Watch the walls bend when balls hit them! The bend depends on impact force.</p>
        </div>
      </div>
    </div>
  );
};

export default BallSimulation;
